// UNITY-DEPENDENT — requires the Unity Editor (UnityEditor + JsonUtility).
// Converts versioned Content/*.json into ScriptableObjects under
// Assets/Scripts/Runtime/Generated/. JSON is the source of truth; generated
// .asset files are git-ignored and regenerated by CI and by Beth.
//
// AI agents: this script may CREATE assets via AssetDatabase, but NEVER hand-edit
// scene/prefab YAML or GUIDs.

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using UnityEditor;
using UnityEngine;
using ScandalSeason.Domain.Economy; // GameRules: chapters/season, scenes/chapter

public static class ContentImporter
{
    public const string ExpectedSchemaVersion = "1.0.0";
    private const string GeneratedRoot = "Assets/Scripts/Runtime/Generated";

    // ------------------------------------------------------------------ menu

    [MenuItem("Scandal Season/Import Content JSON")]
    public static void ImportAll()
    {
        var errors = new List<string>();
        string contentDir = ContentDirectory();

        ImportMergeChains(contentDir, errors);
        ImportOutfits(contentDir, errors);
        ImportScenes(contentDir, errors);
        ImportVoteEvents(contentDir, errors);
        ImportSeasonPasses(contentDir, errors);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        if (errors.Count > 0)
        {
            foreach (var e in errors) Debug.LogError($"[Content] {e}");
            Debug.LogError($"[Content] Import finished with {errors.Count} error(s). Fix Content/*.json and re-import.");
        }
        else
        {
            Debug.Log("[Content] Import complete — all files valid.");
        }

        ExitBatchMode(errors.Count);
    }

    [MenuItem("Scandal Season/Validate Content JSON")]
    public static void ValidateOnly()
    {
        var errors = new List<string>();
        string contentDir = ContentDirectory();

        ValidateFile<MergeChainsFile>(contentDir, "merge-chains.json", errors, ValidateMergeChains);
        ValidateFile<OutfitsFile>(contentDir, "outfits.json", errors, ValidateOutfits);
        ValidateFile<ScenesFile>(contentDir, "scenes.json", errors, ValidateScenes);
        ValidateFile<ScenesFile>(contentDir, "scenes-season2.json", errors, ValidateScenes);
        ValidateFile<ScenesFile>(contentDir, "scenes-season3.json", errors, ValidateScenes);
        ValidateFile<VoteEventsFile>(contentDir, "vote-events.json", errors, ValidateVoteEvents);
        ValidateFile<SeasonPassesFile>(contentDir, "season-passes.json", errors, ValidateSeasonPasses);

        if (errors.Count > 0)
        {
            foreach (var e in errors) Debug.LogError($"[Content] {e}");
            Debug.LogError($"[Content] Validation failed with {errors.Count} error(s).");
        }
        else Debug.Log("[Content] All content files valid.");

        ExitBatchMode(errors.Count);
    }

    // In -batchmode (CI / headless runs), surface failures as a non-zero exit
    // code so automation can fail the job. Never quits the interactive editor.
    private static void ExitBatchMode(int errorCount)
    {
        if (Application.isBatchMode)
            EditorApplication.Exit(errorCount > 0 ? 1 : 0);
    }

    // ------------------------------------------------------------------ io

    private static string ContentDirectory()
    {
        string dir = Path.GetFullPath(Path.Combine(Application.dataPath, "..", "Content"));
        if (!Directory.Exists(dir))
            throw new DirectoryNotFoundException($"Content directory not found: {dir}");
        return dir;
    }

    private static T ReadJson<T>(string contentDir, string fileName, List<string> errors) where T : class
    {
        string path = Path.Combine(contentDir, fileName);
        if (!File.Exists(path))
        {
            errors.Add($"{fileName}: file not found.");
            return null!;
        }
        try
        {
            var parsed = JsonUtility.FromJson<T>(File.ReadAllText(path));
            if (parsed == null) errors.Add($"{fileName}: parsed to null (malformed JSON?).");
            return parsed!;
        }
        catch (Exception ex)
        {
            errors.Add($"{fileName}: JSON parse error: {ex.Message}");
            return null!;
        }
    }

    private static bool CheckSchemaVersion(string fileName, string schemaVersion, List<string> errors, string expected = ExpectedSchemaVersion)
    {
        if (schemaVersion != expected)
        {
            errors.Add($"{fileName}: schemaVersion '{schemaVersion}' != expected '{expected}'.");
            return false;
        }
        return true;
    }

    // Dotted ids namespace content to its board/area (e.g. atelier.notions).
    // The literal "TBD" marks design placeholders the importer skips.
    private static readonly Regex IdPattern = new Regex(@"^([a-z0-9._-]+|TBD)$", RegexOptions.Compiled);

    private static bool CheckId(string fileName, string id, List<string> errors, string what)
    {
        if (string.IsNullOrEmpty(id) || !IdPattern.IsMatch(id))
        {
            errors.Add($"{fileName}: {what} has invalid id '{id}' (must match ^([a-z0-9._-]+|TBD)$).");
            return false;
        }
        return true;
    }

    private static bool CheckSeason(string fileName, string id, int season, List<string> errors)
    {
        // Seasons are endless (Book One is 1–10); only the lower bound is enforced.
        if (season < 1)
        {
            errors.Add($"{fileName}: '{id}' season {season} out of range (must be >= 1).");
            return false;
        }
        return true;
    }

    private static void ValidateFile<T>(string contentDir, string fileName, List<string> errors, Action<string, T, List<string>> validate) where T : class
    {
        var parsed = ReadJson<T>(contentDir, fileName, errors);
        if (parsed != null) validate(fileName, parsed, errors);
    }

    private static string EnsureFolder(string folder)
    {
        if (AssetDatabase.IsValidFolder(folder)) return folder;
        string parent = Path.GetDirectoryName(folder)!.Replace('\\', '/');
        EnsureFolder(parent);
        AssetDatabase.CreateFolder(parent, Path.GetFileName(folder));
        return folder;
    }

    private static string SanitizeAssetName(string id) =>
        Regex.Replace(id, @"[^a-zA-Z0-9-_]", "_");

    private static void SaveDefinition<T>(string subfolder, string id, T asset) where T : ScriptableObject
    {
        string folder = EnsureFolder($"{GeneratedRoot}/{subfolder}");
        string path = $"{folder}/{SanitizeAssetName(id)}.asset";
        if (AssetDatabase.LoadAssetAtPath<T>(path) != null)
            AssetDatabase.DeleteAsset(path);
        AssetDatabase.CreateAsset(asset, path);
    }

    // ------------------------------------------------------------------ merge chains

    [Serializable] private sealed class MergeChainsFile
    {
        public string schemaVersion = "";
        public MergeChainDto[] chains = Array.Empty<MergeChainDto>();
    }
    [Serializable] private sealed class MergeChainDto
    {
        public string id = "";
        public string board = "";
        public string displayName = "";
        public ChainLevelDto[] levels = Array.Empty<ChainLevelDto>();
    }
    [Serializable] private sealed class ChainLevelDto
    {
        public int level;
        public string itemId = "";
        public string name = "";
        public string displayName = "";
        public string artHook = "";
        public string art_notes = "";
        public int baseValue;
        public int unlockSeason = 1;
    }

    private static void ValidateMergeChains(string fileName, MergeChainsFile file, List<string> errors)
    {
        // Design files may not carry a schema version yet — warn, don't fail.
        if (string.IsNullOrEmpty(file.schemaVersion))
            Debug.LogWarning($"[Content] {fileName}: no schemaVersion; assuming {ExpectedSchemaVersion}.");
        else if (file.schemaVersion != ExpectedSchemaVersion)
            Debug.LogWarning($"[Content] {fileName}: schemaVersion '{file.schemaVersion}' != expected '{ExpectedSchemaVersion}'.");
        if (file.chains.Length == 0) errors.Add($"{fileName}: at least one chain is required.");
        var seenIds = new System.Collections.Generic.HashSet<string>();
        var seenItemIds = new System.Collections.Generic.HashSet<string>();
        foreach (var chain in file.chains)
        {
            if (chain.id == "TBD")
            {
                Debug.Log($"[Content] {fileName}: skipping TBD chain '{chain.displayName}' (no id assigned yet).");
                continue;
            }
            if (!CheckId(fileName, chain.id, errors, "chain")) continue;
            if (!seenIds.Add(chain.id))
                errors.Add($"{fileName}: duplicate chain id '{chain.id}'.");
            if (string.IsNullOrWhiteSpace(chain.displayName))
                errors.Add($"{fileName}: chain '{chain.id}' needs a displayName.");
            if (chain.levels.Length != 10)
                errors.Add($"{fileName}: chain '{chain.id}' must have exactly 10 levels (locked engine rule; found {chain.levels.Length}).");
            for (int i = 0; i < chain.levels.Length; i++)
            {
                var lvl = chain.levels[i];
                if (lvl.level != i + 1)
                    errors.Add($"{fileName}: chain '{chain.id}' levels must be sequential from 1 (found {lvl.level} at index {i}).");
                if (string.IsNullOrWhiteSpace(lvl.itemId))
                    errors.Add($"{fileName}: chain '{chain.id}' level {lvl.level} needs an itemId.");
                else if (!seenItemIds.Add(lvl.itemId))
                    errors.Add($"{fileName}: duplicate itemId '{lvl.itemId}' (chain '{chain.id}' level {lvl.level}).");
                if (string.IsNullOrWhiteSpace(lvl.name) && string.IsNullOrWhiteSpace(lvl.displayName))
                    errors.Add($"{fileName}: chain '{chain.id}' level {lvl.level} needs a name.");
                CheckSeason(fileName, $"{chain.id} level {lvl.level}", lvl.unlockSeason, errors);
            }
        }
    }

    private static void ImportMergeChains(string contentDir, List<string> errors)
    {
        var file = ReadJson<MergeChainsFile>(contentDir, "merge-chains.json", errors);
        if (file == null) return;
        int before = errors.Count;
        ValidateMergeChains("merge-chains.json", file, errors);
        if (errors.Count != before) return;
        // Content set changed (placeholder chains replaced by design chains):
        // clear previously generated chain assets so stale ones can't linger.
        foreach (var guid in AssetDatabase.FindAssets("", new[] { $"{GeneratedRoot}/MergeChains" }))
            AssetDatabase.DeleteAsset(AssetDatabase.GUIDToAssetPath(guid));
        foreach (var chain in file.chains)
        {
            if (chain.id == "TBD") continue; // logged in validation
            var so = ScriptableObject.CreateInstance<ItemChainDefinitionSO>();
            so.chainId = chain.id;
            so.board = chain.board;
            so.displayName = chain.displayName;
            so.levels = Array.ConvertAll(chain.levels, l => new ItemChainDefinitionSO.ChainLevel
            {
                level = l.level,
                itemId = l.itemId,
                displayName = !string.IsNullOrWhiteSpace(l.name) ? l.name
                    : !string.IsNullOrWhiteSpace(l.displayName) ? l.displayName
                    : $"TBD (level {l.level})",
                artHook = l.artHook,
                artNotes = l.art_notes,
                baseValue = l.baseValue,
                unlockSeason = l.unlockSeason
            });
            SaveDefinition("MergeChains", chain.id, so);
        }
    }

    // ------------------------------------------------------------------ outfits
    // Wardrobe v2 (locked Sep 27 2026): dual-unit wardrobe. Ensembles are the
    // Daily Vote (competition-side) unit; components are the chapter-dressing
    // (story-side) unit. Rarity: atelier / couture / imperiale / legende.

    [Serializable] private sealed class OutfitsFile
    {
        public string schemaVersion = "";
        public OutfitCollectionDto[] collections = Array.Empty<OutfitCollectionDto>();
        public EnsembleDto[] ensembles = Array.Empty<EnsembleDto>();
    }
