    [Serializable] private sealed class SceneDto
    {
        public string id = "";
        public int season = 1;
        public int chapter = 1;
        public int scene = 1;
        public string chapterTitle = "";
        public string chapterStatus = "";
        public string type = "";
        public string synopsis = "";
        public string[] participants = Array.Empty<string>();
        public string animation = "";
        public string animationNote = "";
        public string beatQualifier = "";
        public int playerTurns;
        public string turnNote = "";
        // Null when the scene carries no key decision / ritual / sting (optional JSON objects).
        public KeyDecisionDto keyDecision;
        public RitualDto ritual;
        public FashionChoiceDto[] fashionChoices;
        public string sting;
        public string sourceFile = "";
    }

    private static SceneType ParseSceneType(string type) => type switch
    {
        "dialogue" => SceneType.Dialogue,
        "fashion-selection" => SceneType.FashionSelection,
        "chapter-climax" => SceneType.ChapterClimax,
        "texture" => SceneType.Texture,
        "plot-beat" => SceneType.PlotBeat,
        "gazette-sting" => SceneType.GazetteSting,
        "cliffhanger" => SceneType.Cliffhanger,
        _ => throw new ArgumentException($"Unknown scene type '{type}'.")
    };

    private static SceneAnimation ParseSceneAnimation(string animation) => animation switch
    {
        "Shared" => SceneAnimation.Shared,
        "Custom" => SceneAnimation.Custom,
        _ => throw new ArgumentException($"Unknown scene animation '{animation}'.")
    };

    private const string ScenesSchemaVersion = "2.1.0";

    // NOTE: JsonUtility instantiates nested [Serializable] DTO objects even when the
    // JSON key is absent, so presence is detected by content, not by null.
    private static bool HasKeyDecision(SceneDto scene) =>
        scene.keyDecision != null && !string.IsNullOrWhiteSpace(scene.keyDecision.title);
    private static bool HasRitual(SceneDto scene) =>
        scene.ritual != null && (!string.IsNullOrWhiteSpace(scene.ritual.occasionBrief)
            || (scene.ritual.directions != null && scene.ritual.directions.Length > 0)
            || (scene.ritual.steps != null && scene.ritual.steps.Length > 0)
            || !string.IsNullOrWhiteSpace(scene.ritual.part));

    private static void ValidateScenes(string fileName, ScenesFile file, List<string> errors)
    {
        if (!CheckSchemaVersion(fileName, file.schemaVersion, errors, ScenesSchemaVersion)) return;
        if (file.scenes.Length == 0) errors.Add($"{fileName}: at least one scene is required.");
        foreach (var scene in file.scenes)
        {
            if (!CheckId(fileName, scene.id, errors, "scene")) continue;
            CheckSeason(fileName, scene.id, scene.season, errors);
            if (scene.chapter < 1 || scene.chapter > GameRules.ChaptersPerSeason)
                errors.Add($"{fileName}: scene '{scene.id}' chapter {scene.chapter} out of range (1–{GameRules.ChaptersPerSeason}).");
            if (scene.scene < 1 || scene.scene > GameRules.ScenesPerChapter)
                errors.Add($"{fileName}: scene '{scene.id}' scene number {scene.scene} out of range (1–{GameRules.ScenesPerChapter}).");
            if (string.IsNullOrWhiteSpace(scene.chapterTitle))
                errors.Add($"{fileName}: scene '{scene.id}' needs a chapterTitle.");
            if (scene.chapterStatus != "FULL" && scene.chapterStatus != "PILOT")
                errors.Add($"{fileName}: scene '{scene.id}' chapterStatus '{scene.chapterStatus}' must be FULL or PILOT.");
            SceneType parsed;
            try { parsed = ParseSceneType(scene.type); }
            catch { errors.Add($"{fileName}: scene '{scene.id}' has unknown type '{scene.type}'."); continue; }
            try { ParseSceneAnimation(scene.animation); }
            catch { errors.Add($"{fileName}: scene '{scene.id}' has unknown animation '{scene.animation}'."); }
            if (parsed == SceneType.ChapterClimax && !HasRitual(scene))
                errors.Add($"{fileName}: chapter-climax scene '{scene.id}' requires ritual content (brief, directions, steps, or part label).");
            if (parsed == SceneType.GazetteSting && string.IsNullOrWhiteSpace(scene.sting))
                errors.Add($"{fileName}: gazette-sting scene '{scene.id}' requires sting text.");
            if (parsed == SceneType.FashionSelection && scene.fashionChoices == null)
                errors.Add($"{fileName}: fashion-selection scene '{scene.id}' requires fashionChoices (may be empty).");
            if (HasKeyDecision(scene))
            {
                if (scene.keyDecision.number < 1 || scene.keyDecision.number > 3)
                    errors.Add($"{fileName}: scene '{scene.id}' key decision number {scene.keyDecision.number} out of range (1–3).");
                if (string.IsNullOrWhiteSpace(scene.keyDecision.title))
                    errors.Add($"{fileName}: scene '{scene.id}' key decision needs a title.");
                if (scene.keyDecision.options == null || scene.keyDecision.options.Length < 2)
                    errors.Add($"{fileName}: scene '{scene.id}' key decision needs at least 2 options.");
            }
        }
        // Locked container: every listed chapter must hold exactly 40 scenes,
        // exactly 3 key decisions, 1 ritual, 1 sting, and 1 cliffhanger.
        foreach (var group in file.scenes.GroupBy(s => (s.season, s.chapter)).OrderBy(g => g.Key))
        {
            var key = group.Key;
            var list = group.ToList();
            if (list.Count != GameRules.ScenesPerChapter)
                errors.Add($"{fileName}: season {key.season}, chapter {key.chapter} has {list.Count}/{GameRules.ScenesPerChapter} scenes.");
            var numbers = list.Select(s => s.scene).OrderBy(n => n).ToList();
            if (!numbers.SequenceEqual(Enumerable.Range(1, GameRules.ScenesPerChapter)))
                errors.Add($"{fileName}: season {key.season}, chapter {key.chapter} scene numbers are not 1–{GameRules.ScenesPerChapter}.");
            var decisions = list.Where(HasKeyDecision).Select(s => s.keyDecision.number).OrderBy(n => n).ToList();
            if (!decisions.SequenceEqual(new[] { 1, 2, 3 }))
                errors.Add($"{fileName}: season {key.season}, chapter {key.chapter} key decisions are [{string.Join(",", decisions)}], expected 1,2,3.");
            // Locked container: every listed chapter must hold exactly 40 scenes,
            // exactly 3 key decisions, 1 contiguous dressing-ritual group, 1 sting,
            // and 1 cliffhanger. Multi-part rituals (Season Two) are one group.
            var ritualScenes = list.Where(s => s.type == "chapter-climax").OrderBy(s => s.scene).ToList();
            int ritualGroups = 0;
            int prevScene = -2;
            foreach (var rs in ritualScenes)
            {
                if (rs.scene != prevScene + 1) ritualGroups++;
                prevScene = rs.scene;
            }
            if (ritualGroups != 1)
                errors.Add($"{fileName}: season {key.season}, chapter {key.chapter} must have exactly 1 dressing ritual group, found {ritualGroups}.");
            else if (!ritualScenes.Any(s => !string.IsNullOrWhiteSpace(s.ritual?.occasionBrief)))
                errors.Add($"{fileName}: season {key.season}, chapter {key.chapter} ritual group needs at least one occasion brief.");
            if (list.Count(s => s.type == "gazette-sting") != 1)
                errors.Add($"{fileName}: season {key.season}, chapter {key.chapter} must have exactly 1 Gazette sting.");
            if (list.Count(s => s.type == "cliffhanger") != 1)
                errors.Add($"{fileName}: season {key.season}, chapter {key.chapter} must have exactly 1 cliffhanger.");
        }
    }

    private static void ImportScenes(string contentDir, List<string> errors)
    {
        foreach (var fileName in new[] { "scenes.json", "scenes-season2.json", "scenes-season3.json" })
        {
            var file = ReadJson<ScenesFile>(contentDir, fileName, errors);
            if (file == null) continue;
            int before = errors.Count;
            ValidateScenes(fileName, file, errors);
            if (errors.Count != before) continue;
            foreach (var scene in file.scenes) ImportScene(scene);
        }
    }

    private static void ImportScene(SceneDto scene)
    {
            var so = ScriptableObject.CreateInstance<SceneDefinitionSO>();
            so.sceneId = scene.id;
            so.season = scene.season;
            so.chapter = scene.chapter;
            so.sceneNumber = scene.scene;
            so.chapterTitle = scene.chapterTitle;
            so.chapterStatus = scene.chapterStatus;
            so.type = ParseSceneType(scene.type);
            so.synopsis = scene.synopsis;
            so.participants = scene.participants ?? Array.Empty<string>();
            so.animation = ParseSceneAnimation(scene.animation);
            so.animationNote = scene.animationNote;
            so.beatQualifier = scene.beatQualifier;
            so.playerTurns = scene.playerTurns;
            so.turnNote = scene.turnNote ?? "";
            if (HasKeyDecision(scene))
            {
                so.keyDecision = new KeyDecisionData
                {
                    number = scene.keyDecision.number,
                    title = scene.keyDecision.title,
                    options = (scene.keyDecision.options ?? Array.Empty<DecisionOptionDto>())
                        .Select(o => new DecisionOptionData { label = o.label, detail = o.detail }).ToArray()
                };
            }
            if (HasRitual(scene))
            {
                so.ritual = new RitualData
                {
                    part = scene.ritual.part ?? "",
                    occasionBrief = scene.ritual.occasionBrief ?? "",
                    directions = scene.ritual.directions ?? Array.Empty<string>(),
                    stepsSummary = scene.ritual.stepsSummary ?? "",
                    steps = scene.ritual.steps ?? Array.Empty<string>(),
                    coinPerDecision = scene.ritual.coinPerDecision,
                    coinTotal = scene.ritual.coinTotal
                };
            }
            so.fashionChoices = (scene.fashionChoices ?? Array.Empty<FashionChoiceDto>())
                .Select(c => new FashionChoiceData { label = c.label, detail = c.detail }).ToArray();
            so.sting = scene.sting ?? "";
            so.sourceFile = scene.sourceFile;
            so.coinPrice = ComputeScenePrice(scene);
            SaveDefinition("Scenes", scene.id, so);
    }

    /// <summary>
    /// LOCKED Sep 27 (Beth): price = 120 + 15 per item decision + 25 per
    /// color/finish decision + 60 if major plot point, capped at 290.
    /// Item decisions = ritual steps (non-color/finish) + fashion choices.
    /// Color/finish decisions = ritual steps naming color, fabric, finish, etc.
    /// Major plot point = scene carries a key decision.
    /// </summary>
    private static int ComputeScenePrice(SceneDto scene)
    {
        int itemDecisions = 0;
        int colorFinishDecisions = 0;

        if (scene.ritual?.steps != null)
        {
            foreach (var step in scene.ritual.steps)
            {
                if (IsColorFinishStep(step)) colorFinishDecisions++;
                else itemDecisions++;
            }
        }
        if (scene.fashionChoices != null)
            itemDecisions += scene.fashionChoices.Length;

        int price = 120 + 15 * itemDecisions + 25 * colorFinishDecisions;
        if (scene.keyDecision != null) price += 60;
        return Math.Min(290, price);
    }

    private static bool IsColorFinishStep(string step)
    {
        var lower = step.ToLowerInvariant();
        return lower.Contains("color") || lower.Contains("fabric") ||
               lower.Contains("finish") || lower.Contains("trim") ||
               lower.Contains("thread") || lower.Contains("lace") ||
               lower.Contains("embroidery");
    }

    // ------------------------------------------------------------------ vote events

    [Serializable] private sealed class VoteEventsFile
    {
        public string schemaVersion = "";
        public VoteEventDto[] voteEvents = Array.Empty<VoteEventDto>();
    }
    [Serializable] private sealed class VoteEventDto
    {
        public string id = "";
        public string date = "";
        public string gazettePrompt = "";
        public VoteLookDto lookA = new VoteLookDto();
        public VoteLookDto lookB = new VoteLookDto();
    }
    [Serializable] private sealed class VoteLookDto
    {
        public string label = "";
        public string outfitId = "";
        public string stylist = "";
    }

    private static void ValidateVoteEvents(string fileName, VoteEventsFile file, List<string> errors)
    {
        if (!CheckSchemaVersion(fileName, file.schemaVersion, errors)) return;
        if (file.voteEvents.Length == 0) errors.Add($"{fileName}: at least one vote event is required.");
        foreach (var vote in file.voteEvents)
        {
            if (!CheckId(fileName, vote.id, errors, "vote event")) continue;
            CheckVoteLook(fileName, vote.id, "lookA", vote.lookA, errors);
            CheckVoteLook(fileName, vote.id, "lookB", vote.lookB, errors);
        }
    }

    private static void CheckVoteLook(string fileName, string voteId, string side, VoteLookDto look, List<string> errors)
    {
        if (look == null || string.IsNullOrWhiteSpace(look.label) || string.IsNullOrWhiteSpace(look.outfitId))
            errors.Add($"{fileName}: vote '{voteId}' {side} needs a label and outfitId.");
    }

    private static void ImportVoteEvents(string contentDir, List<string> errors)
    {
        var file = ReadJson<VoteEventsFile>(contentDir, "vote-events.json", errors);
        if (file == null) return;
        int before = errors.Count;
        ValidateVoteEvents("vote-events.json", file, errors);
        if (errors.Count != before) return;
        foreach (var vote in file.voteEvents)
        {
            var so = ScriptableObject.CreateInstance<VoteEventDefinitionSO>();
            so.voteId = vote.id;
            so.date = vote.date;
            so.gazettePrompt = vote.gazettePrompt;
            so.lookA = ToVoteLook(vote.lookA);
            so.lookB = ToVoteLook(vote.lookB);
            SaveDefinition("VoteEvents", vote.id, so);
        }
    }

    private static VoteEventDefinitionSO.VoteLook ToVoteLook(VoteLookDto dto) =>
        new VoteEventDefinitionSO.VoteLook { label = dto.label, outfitId = dto.outfitId, stylist = dto.stylist };

    // ------------------------------------------------------------------ season passes

    [Serializable] private sealed class SeasonPassesFile
    {
        public string schemaVersion = "";
        public SeasonPassDto[] passes = Array.Empty<SeasonPassDto>();
    }
    [Serializable] private sealed class SeasonPassDto
    {
        public string id = "";
        public string displayName = "";
        public int season = 1;
        public int durationDays = 7;
        public PassTierDto[] tiers = Array.Empty<PassTierDto>();
    }
    [Serializable] private sealed class PassTierDto
    {
        public int tier;
        public int crownPrice = -1; // absent/negative = time-only, never purchasable
        public PassRewardDto[] rewards = Array.Empty<PassRewardDto>();
    }
    [Serializable] private sealed class PassRewardDto
    {
        public string rewardId = "";
        public float timeToEarnDays;
        public string earnDescription = "";
    }

    private static void ValidateSeasonPasses(string fileName, SeasonPassesFile file, List<string> errors)
    {
        if (!CheckSchemaVersion(fileName, file.schemaVersion, errors)) return;
        if (file.passes.Length == 0) errors.Add($"{fileName}: at least one pass is required.");
        foreach (var pass in file.passes)
        {
            if (!CheckId(fileName, pass.id, errors, "pass")) continue;
            CheckSeason(fileName, pass.id, pass.season, errors);
            if (pass.durationDays < 3 || pass.durationDays > 14)
                errors.Add($"{fileName}: pass '{pass.id}' durationDays {pass.durationDays} out of range (3–14).");
            if (pass.tiers.Length == 0)
                errors.Add($"{fileName}: pass '{pass.id}' needs at least one tier.");
            foreach (var tier in pass.tiers)
            {
                if (tier.rewards.Length == 0)
                    errors.Add($"{fileName}: pass '{pass.id}' tier {tier.tier} needs at least one reward.");
                foreach (var reward in tier.rewards)
                {
                    // Iron rule, enforced at import: every reward declares its time path.
                    if (reward.timeToEarnDays <= 0)
                        errors.Add($"{fileName}: pass '{pass.id}' reward '{reward.rewardId}' needs timeToEarnDays > 0 (iron rule).");
                    if (string.IsNullOrWhiteSpace(reward.earnDescription))
                        errors.Add($"{fileName}: pass '{pass.id}' reward '{reward.rewardId}' needs an earnDescription (iron rule).");
                }
            }
        }
    }

    private static void ImportSeasonPasses(string contentDir, List<string> errors)
    {
        var file = ReadJson<SeasonPassesFile>(contentDir, "season-passes.json", errors);
        if (file == null) return;
        int before = errors.Count;
        ValidateSeasonPasses("season-passes.json", file, errors);
        if (errors.Count != before) return;
        foreach (var pass in file.passes)
        {
            var so = ScriptableObject.CreateInstance<SeasonPassDefinitionSO>();
            so.passId = pass.id;
            so.displayName = pass.displayName;
            so.season = pass.season;
            so.durationDays = pass.durationDays;
            so.tiers = Array.ConvertAll(pass.tiers, t => new SeasonPassDefinitionSO.PassTier
            {
                tier = t.tier,
                purchasable = t.crownPrice >= 0,
                crownPrice = Math.Max(0, t.crownPrice),
                rewards = Array.ConvertAll(t.rewards, r => new SeasonPassDefinitionSO.PassReward
                {
                    rewardId = r.rewardId,
                    timeToEarnDays = r.timeToEarnDays,
                    earnDescription = r.earnDescription
                })
            });
            SaveDefinition("SeasonPasses", pass.id, so);
        }
    }
}
